export type QuizQuestion = { q: string; options: string[]; correct: number; explanation: string }
export type Lesson = {
  id: string
  title: string
  duration: number
  goal: string
  sections: { title: string; text: string }[]
  keyFacts: string[]
  example: string
  practice: string
  quiz: QuizQuestion[]
}
export type Subject = {
  id: string
  title: string
  control: 'Зачёт' | 'Экзамен' | 'Практикум'
  semester: number
  icon: string
  tone: string
  description: string
  lessons: Lesson[]
}

const q = (q: string, options: string[], correct: number, explanation: string): QuizQuestion => ({ q, options, correct, explanation })
const l = (id: string, title: string, duration: number, goal: string, sections: { title: string; text: string }[], keyFacts: string[], example: string, practice: string, quiz: QuizQuestion[]): Lesson => ({ id, title, duration, goal, sections, keyFacts, example, practice, quiz })

